 fields=['authority_type','county','county_fips','rank','priority','authority_url','county_urls','observed_sources','discovery_depth','current_november_admitted','current_election_id','current_contest_id','current_candidate_ids','current_unit_ids','current_method_ids','source_timestamp','source_timezone','source_status','completion_semantics','cadence','corrections','finding','full_record_locator']
 rows=[]
 rows.append(dict.fromkeys(fields,''));rows[0].update(authority_type='state',county='South Carolina State Election Commission',authority_url='https://scvotes.gov/elections-statistics/election-results/',observed_sources='../news/sos-results.html.gz; raw/candidate-elections.meta.json',discovery_depth='official index and client chains + historical all46 originals independently audited',current_november_admitted='false',source_status='no current November results verified',cadence='no measured November cadence',corrections='replace compatible cumulative snapshots; retain every revision',full_record_locator='state-channels.json',finding='Candidate tracker election22596 is verified; ENR November IDs are not. Results index includes June and August stages; no test/old counts admitted.')
